const countryCodes={India:'IN','United States':'US','United Kingdom':'GB',Canada:'CA',Australia:'AU',Germany:'DE',Singapore:'SG','United Arab Emirates':'AE'};
const marketNotes=[{"countries":["India","United States","United Kingdom","Singapore"],"india":"Offer a bilingual WhatsApp follow-up and invoicing pilot for one local business segment. Validate willingness to pay with shop owners."},{"countries":["India","Germany","United Kingdom"],"india":"Test a neighborhood phone-repair and refurbished-device service in Bengaluru, Delhi NCR, or your own city. Verify repair quality and unit economics."},{"countries":["India","United States","Australia"],"india":"Test regional-language habit coaching for working professionals. Partner with qualified specialists and validate a paid cohort."},{"countries":["India","United States","Singapore"],"india":"Pilot short, mobile-first workplace lessons in English and a regional language with a local employer."},{"countries":["United States","United Kingdom","Singapore"],"india":"Explore a document assistant for an Indian professional niche, with human review and explicit data privacy controls."},{"countries":["India","United Kingdom","United Arab Emirates"],"india":"Pre-sell one local workshop or food walk with verified hosts. Start in your own city and check local permissions."},{"countries":["India","Germany","Australia"],"india":"Offer a packaging audit to local online sellers. Validate supplier minimum orders, material claims, shipping costs, and applicable rules."},{"countries":["India","United States","United Kingdom"],"india":"Test multilingual product FAQs and human handoff for one Indian online retailer. Measure answer quality before expanding."},{"countries":["United States","Canada","Australia"],"india":"Test patient device support with families and senior communities in your city. Design local-language sessions and clear fraud-prevention guidance."},{"countries":["India","United States","United Kingdom"],"india":"Pilot sponsor tracking and invoice reminders with regional-language creators. Validate their existing workflows and budget."},{"countries":["India","Canada","United Kingdom"],"india":"Offer a focused portfolio workshop for one career transition. Interview hiring managers and avoid job-placement guarantees."},{"countries":["India","Australia","United Arab Emirates"],"india":"Pre-sell weekend classes in an apartment community with qualified instructors. Check venue permission, safety, and insurance."}];
ideas.forEach((idea,index)=>{idea.countries=marketNotes[index].countries;idea.india=marketNotes[index].india;});
function trendsUrl(query,country){return 'https://trends.google.com/trends/explore?'+new URLSearchParams({date:'today 12-m',q:query,...(countryCodes[country]?{geo:countryCodes[country]}:{})}).toString();}
function marketDetails(i){const country=$('#country').value;const chosen=country==='all'?'India':country;return '<h3>Country opportunities · curated suggestions</h3><p>'+i.countries.join(' · ')+'</p><h3>India-specific pilot</h3><p>'+i.india+'</p><p class="notice">Suggested markets are editorial hypotheses, not a ranking of popularity. Hacker News does not provide country-level demand data. All startup budgets on cards are in USD.</p><p><a class="market-link" href="'+trendsUrl(i.title,chosen)+'" target="_blank" rel="noopener noreferrer">Check search interest in '+chosen+' on Google Trends ↗</a></p><p>Google Trends shows relative search interest, not sales or market size. Try shorter keywords if the exact idea has insufficient data.</p>';}
let saved;try{saved=new Set(JSON.parse(localStorage.getItem('vs-saved')||'[]'))}catch{saved=new Set()}let selected=new Set(),category='All ideas',page='explore';const $=s=>document.querySelector(s);const colors=[['#edf0e6','#728156'],['#e8efea','#578071'],['#f4eae4','#aa8165'],['#eceaf5','#8c7ca4'],['#e8eef4','#65839e'],['#f6efdc','#ac9452']];
function render(){const query=$('#search').value.toLowerCase(),budget=$('#budget').value;let data=ideas.filter(i=>($('#country').value==='all'||i.countries.includes($('#country').value))&&(page!=='saved'||saved.has(i.id))&&(category==='All ideas'||i.category===category)&&(`${i.title} ${i.category} ${i.description}`.toLowerCase().includes(query))&&(budget==='all'||(budget==='low'?i.cost<5000:i.cost>=5000)));data.sort((a,b)=>$('#sort').value==='growth'?b.growth-a.growth:$('#sort').value==='cost'?a.cost-b.cost:b.score-a.score);$('#results').textContent=`(${data.length})`;$('#savedCount').textContent=saved.size;$('#listTitle').firstChild.textContent=page==='saved'?'Your saved ideas ':'Explore the sample idea catalog ';$('#chips').innerHTML=['All ideas','AI & Automation','Sustainability','Health & Wellness','Education','Lifestyle','Creator Economy'].map(c=>`<button class="chip ${c===category?'active':''}" data-category="${c}">${c}</button>`).join('');$('#grid').innerHTML=data.map(i=>{let c=colors[i.id%6];return `<article class="card" style="--tint:${c[0]};--color:${c[1]}"><div class="card-top"><div class="icon">${i.icon}</div><button class="save ${saved.has(i.id)?'saved':''}" data-save="${i.id}" aria-label="${saved.has(i.id)?'Unsave':'Save'} ${i.title}" aria-pressed="${saved.has(i.id)}">${saved.has(i.id)?'▣':'♧'}</button></div><div class="tag">${i.category}</div><h3>${i.title}</h3><p>${i.description}</p><div class="market-badges"><span>Suggested markets</span><strong>${i.countries.join(" · ")}</strong></div><div class="trend"><svg viewBox="0 0 210 45" preserveAspectRatio="none" aria-label="Illustrative upward trend"><path d="M0 40 L15 35 29 37 42 29 57 33 72 25 87 28 102 19 117 22 132 15 147 17 162 10 178 13 193 4 210 1 L210 45 L0 45Z" fill="#edf4e7"/><path d="M0 40 L15 35 29 37 42 29 57 33 72 25 87 28 102 19 117 22 132 15 147 17 162 10 178 13 193 4 210 1" fill="none" stroke="#7c9e61" stroke-width="2"/></svg><span class="growth">+${i.growth}%<small>sample growth</small></span></div><div class="card-meta"><span>Startup budget<strong>${i.budget}</strong></span><span>Business model<strong>${i.model}</strong></span></div><div class="card-foot"><span class="score">Potential <b>${i.score}</b><small> / 100</small></span><button class="view" data-view="${i.id}">Explore idea &nbsp; ↗</button></div><label class="check"><input type="checkbox" data-select="${i.id}" ${selected.has(i.id)?'checked':''}> Add to comparison</label></article>`}).join('')||'<div class="empty">No ideas found. Try another filter or save an idea to start your collection.</div>';$('#comparebar').style.display=selected.size?'flex':'none';$('#selectedCount').textContent=`${selected.size} idea${selected.size===1?'':'s'} selected`;}
function show(html){$('#modalContent').innerHTML=html;$('#modal').showModal()}function compare(){if(selected.size<2){show('<div class="eyebrow">SIDE BY SIDE</div><h2>Pick your possibilities.</h2><p>Select two or three ideas using “Add to comparison” on each card, then compare startup budget, launch time, and potential.</p>');return}let a=ideas.filter(i=>selected.has(i.id));show(`<div class="eyebrow">SIDE BY SIDE</div><h2>Compare your next moves.</h2><div style="overflow-x:auto"><table><tr><th>Opportunity</th>${a.map(i=>`<th>${i.title}</th>`).join('')}</tr>${[['Suggested markets³','countries'],['Category','category'],['Potential¹','score'],['Sample growth¹','growth'],['Startup budget²','budget'],['Time to pilot²','time'],['Model','model']].map(([name,key])=>`<tr><td>${name}</td>${a.map(i=>`<td>${i[key]}${key==='growth'?'%':key==='score'?'/100':''}</td>`).join('')}</tr>`).join('')}</table></div><p class="notice">¹ Illustrative scores and growth, not live market measurements. ² Planning estimates in USD; actual costs and timing vary. ³ Curated market suggestions, not measured popularity.</p>`)}
document.addEventListener('click',e=>{let t=e.target.closest('button');if(!t)return;if(t.dataset.category){category=t.dataset.category;render()}if(t.dataset.save!==undefined){let id=+t.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('vs-saved',JSON.stringify([...saved]))}catch{}render()}if(t.dataset.view!==undefined){let i=ideas[+t.dataset.view];show(`<div class="eyebrow">${i.category}</div><h2>${i.title}</h2><p>${i.description}</p><span class="pill">${i.budget} estimated startup</span><span class="pill">${i.time} to pilot</span><span class="pill">${i.model}</span>${marketDetails(i)}<h3>The opportunity</h3><p>${i.concept}</p><h3>Your first validation experiment</h3><p>${i.validation}</p><h3>Questions to answer</h3><ul><li>Who has this problem often enough to pay for a solution?</li><li>What do they use today, and why would they switch?</li><li>Can you deliver a paid pilot before investing in a full product?</li></ul><p class="notice">Exploration example. Scores, trend charts and growth percentages are illustrative; budgets and timing are planning estimates. Validate demand with primary research.</p>`)}if(t.dataset.page){page=t.dataset.page;category='All ideas';document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n===t));$('.breadcrumb strong').textContent='/   '+(page==='saved'?'Saved ideas':'Explore ideas');render()}});
document.addEventListener('change',e=>{if(e.target.dataset.select!==undefined){let id=+e.target.dataset.select;if(e.target.checked&&selected.size===3){e.target.checked=false;show('<h2>Keep it focused.</h2><p>Compare up to three ideas at a time. Deselect an idea to choose another.</p>');return}e.target.checked?selected.add(id):selected.delete(id);render()}});['search','budget','sort','country'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',render));$('#spotlight').onclick=()=>{category='AI & Automation';page='explore';render();$('#listTitle').scrollIntoView({behavior:'smooth'})};$('#compareBtn').onclick=compare;$('#compareNav').onclick=compare;$('#clearCompare').onclick=()=>{selected.clear();render()};$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});$('#how').onclick=()=>show('<div class="eyebrow">A LITTLE DIRECTION</div><h2>Follow your curiosity.</h2><p>Search 12 curated business concepts, filter by country, industry and budget, and save the ideas that resonate. Compare up to three opportunities to choose your next experiment.</p><h3>What the numbers mean</h3><p>Potential scores, trend lines, and growth percentages are illustrative examples, not measured or live market data. Budgets and launch times are rough planning estimates. Country tags are suggested markets, not verified popularity rankings. Check the country-specific Google Trends links and validate locally. Use each idea’s validation experiment to gather real evidence.</p><h3>Your personal workspace</h3><p>Saved ideas stay in this browser using local storage. There is no account sync. Use Live Internet Research for on-demand discussion signals; curated card scores remain illustrative.</p>');$('#guide').onclick=()=>show('<div class="eyebrow">FROM IDEA TO EVIDENCE</div><h2>Start small. Learn quickly.</h2><ol><li><b>Choose one audience.</b> Describe a specific group and the problem you believe they have.</li><li><b>Talk to 10 people.</b> Ask about their last experience with the problem and what it cost them.</li><li><b>Map alternatives.</b> Look at competitors, manual workarounds, prices, and switching costs.</li><li><b>Offer a paid pilot.</b> Test willingness to pay with a clear, limited offer.</li><li><b>Decide with evidence.</b> Review conversion, delivery costs, customer outcomes, and repeat interest before investing further.</li></ol>');render();

// Research links share the live research form instead of using illustrative scores.
document.addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(!b)return;const i=ideas[Number(b.dataset.view)];const button=document.createElement('button');button.className='research-link';button.textContent='Research this idea with live sources ↗';button.onclick=()=>{document.querySelector('#modal').close();const q=document.querySelector('#researchQuery');q.value=i.title;document.querySelector('#researchForm').requestSubmit();document.querySelector('#research').scrollIntoView({behavior:'smooth'});};document.querySelector('#modalContent').append(button);});
